binomial_heap_num_entries' ?heap \<equiv>
do {
  guard (\<lambda>s. c_guard ?heap);
  gets (\<lambda>s. num_values_C (h_val (hrs_mem (t_hrs_' s)) ?heap))
}

binomial_tree_unref' ?tree \<equiv>
unless (?tree = NULL)
 (do {
    guard (\<lambda>s. c_guard ?tree);
    guard
     (\<lambda>s.
         - INT_MAX - 1
         < uint (refcount_C (h_val (hrs_mem (t_hrs_' s)) ?tree)));
    guard
     (\<lambda>s.
         uint (refcount_C (h_val (hrs_mem (t_hrs_' s)) ?tree))
         \<le> INT_MAX + 1);
    modify
     (t_hrs_'_update
       (\<lambda>a.
           hrs_mem_update
            (heap_update ?tree
              (refcount_C_update (\<lambda>a. a - 1)
                (h_val (hrs_mem a) ?tree)))
            a));
    condition (\<lambda>s.
                  UCAST(16 \<rightarrow> 32 signed)
                   (refcount_C (h_val (hrs_mem (t_hrs_' s)) ?tree)) =
                  0)
      (do {
         i \<leftarrow>
           whileLoop (\<lambda>i s.
                         i <s UCAST(16 \<rightarrow> 32 signed)
                               (order_C
                                 (h_val (hrs_mem (t_hrs_' s)) ?tree)))
             (\<lambda>i.
                 do {
                   guard
                    (\<lambda>s.
                        c_guard
                         (subtrees_C
                           (h_val (hrs_mem (t_hrs_' s)) ?tree) +\<^sub>p
                          sint i));
                   tree \<leftarrow>
                     gets
                      (\<lambda>s.
                          h_val (hrs_mem (t_hrs_' s))
                           (subtrees_C
                             (h_val (hrs_mem (t_hrs_' s)) ?tree) +\<^sub>p
                            sint i));
                   ret \<leftarrow> binomial_tree_unref' tree;
                   guard (\<lambda>s. 0 \<le> 2147483649 + sint i);
                   guard (\<lambda>s. sint i < INT_MAX);
                   return (i + 1)
                 })
            0;
         ptr \<leftarrow>
           gets
            (\<lambda>s.
                PTR_COERCE(StrictC'_BinomialTree_C ptr \<rightarrow> unit)
                 (subtrees_C (h_val (hrs_mem (t_hrs_' s)) ?tree)));
         ret \<leftarrow> free' ptr;
         free'
          (PTR_COERCE(StrictC'_BinomialTree_C \<rightarrow> unit) ?tree)
       })
      skip
  })

binomial_heap_merge_undo' ?new_roots ?count \<equiv>
do {
  i \<leftarrow>
    whileLoop (\<lambda>i s. i \<le> ?count)
      (\<lambda>i.
          do {
            guard (\<lambda>_. c_guard (?new_roots +\<^sub>p uint i));
            tree \<leftarrow>
              gets
               (\<lambda>s.
                   h_val (hrs_mem (t_hrs_' s))
                    (?new_roots +\<^sub>p uint i));
            ret \<leftarrow> binomial_tree_unref' tree;
            return (i + 1)
          })
     0;
  free'
   (PTR_COERCE(StrictC'_BinomialTree_C ptr \<rightarrow> unit) ?new_roots)
}

binomial_heap_merge' ?heap ?other \<equiv>
do {
  vals \<leftarrow> unknown;
  guard (\<lambda>s. c_guard ?heap);
  guard (\<lambda>s. c_guard ?other);
  max \<leftarrow>
    condition (\<lambda>s.
                  roots_length_C (h_val (hrs_mem (t_hrs_' s)) ?other)
                  < roots_length_C (h_val (hrs_mem (t_hrs_' s)) ?heap))
      (gets
        (\<lambda>xc.
            roots_length_C (h_val (hrs_mem (t_hrs_' xc)) ?heap) + 1))
      (gets
        (\<lambda>xc.
            roots_length_C (h_val (hrs_mem (t_hrs_' xc)) ?other) + 1));
  ret'ptr_to_void'1 \<leftarrow>
    malloc'
     (word_of_nat (size_of TYPE(StrictC'_BinomialTree_C ptr)) *
      UCAST(32 \<rightarrow> 64) max);
  new_roots \<leftarrow>
    return
     (PTR_COERCE(unit \<rightarrow> StrictC'_BinomialTree_C ptr)
       ret'ptr_to_void'1);
  condition (\<lambda>s. new_roots = NULL)
    (return 0)
    (finally
      (do {
         (carry, i, new_roots_length, vals) \<leftarrow>
           whileLoop (\<lambda>(carry, i, new_roots_length, vals) s.
                         i < max)
             (\<lambda>(carry, i, new_roots_length, vals).
                 do {
                   ret \<leftarrow>
                     gets
                      (\<lambda>xg.
                          i < roots_length_C
                               (h_val (hrs_mem (t_hrs_' xg)) ?heap));
                   ret \<leftarrow>
                     liftE
                      (do {
                         guard
                          (\<lambda>xi.
                              ret \<longrightarrow>
                              c_guard
                               (roots_C
                                 (h_val (hrs_mem (t_hrs_' xi))
                                   ?heap) +\<^sub>p
                                uint i));
                         gets
                          (\<lambda>xi.
                              if ret \<and>
                                 h_val (hrs_mem (t_hrs_' xi))
                                  (roots_C
                                    (h_val (hrs_mem (t_hrs_' xi))
?heap) +\<^sub>p
                                   uint i) \<noteq>
                                 NULL
                              then 1 else 0)
                       });
                   (num_vals, vals) \<leftarrow>
                     liftE
                      (condition (\<lambda>s. ret \<noteq> 0)
                         (do {
                            guard
                             (\<lambda>s.
                                 c_guard
                                  (roots_C
                                    (h_val (hrs_mem (t_hrs_' s))
?heap) +\<^sub>p
                                   uint i));
                            vals \<leftarrow>
                              gets
                               (\<lambda>xj.
                                   Arrays.update vals 0
                                    (h_val (hrs_mem (t_hrs_' xj))
(roots_C (h_val (hrs_mem (t_hrs_' xj)) ?heap) +\<^sub>p uint i)));
                            return (1, vals)
                          })
                         (return (0, vals)));
                   ret \<leftarrow>
                     gets
                      (\<lambda>xi.
                          i < roots_length_C
                               (h_val (hrs_mem (t_hrs_' xi)) ?other));
                   ret \<leftarrow>
                     liftE
                      (do {
                         guard
                          (\<lambda>xk.
                              ret \<longrightarrow>
                              c_guard
                               (roots_C
                                 (h_val (hrs_mem (t_hrs_' xk))
                                   ?other) +\<^sub>p
                                uint i));
                         gets
                          (\<lambda>xk.
                              if ret \<and>
                                 h_val (hrs_mem (t_hrs_' xk))
                                  (roots_C
                                    (h_val (hrs_mem (t_hrs_' xk))
?other) +\<^sub>p
                                   uint i) \<noteq>
                                 NULL
                              then 1 else 0)
                       });
                   (num_vals, vals) \<leftarrow>
                     liftE
                      (condition (\<lambda>s. ret \<noteq> 0)
                         (do {
                            guard (\<lambda>s. num_vals <s 3);
                            guard (\<lambda>s. 0 \<le>s num_vals);
                            guard
                             (\<lambda>s.
                                 c_guard
                                  (roots_C
                                    (h_val (hrs_mem (t_hrs_' s))
?other) +\<^sub>p
                                   uint i));
                            guard (\<lambda>s. sint num_vals < INT_MAX);
                            vals \<leftarrow>
                              gets
                               (\<lambda>xl.
                                   Arrays.update vals (unat num_vals)
                                    (h_val (hrs_mem (t_hrs_' xl))
(roots_C (h_val (hrs_mem (t_hrs_' xl)) ?other) +\<^sub>p uint i)));
                            return (num_vals + 1, vals)
                          })
                         (return (num_vals, vals)));
                   (num_vals, vals) \<leftarrow>
                     liftE
                      (condition (\<lambda>s. carry \<noteq> NULL)
                         (do {
                            guard (\<lambda>s. num_vals <s 3);
                            guard (\<lambda>s. 0 \<le>s num_vals);
                            guard (\<lambda>s. sint num_vals < INT_MAX);
                            return
                             (num_vals + 1,
                              Arrays.update vals (unat num_vals) carry)
                          })
                         (return (num_vals, vals)));
                   new_roots_length \<leftarrow>
                     liftE
                      (condition (\<lambda>s. num_vals && 1 = 1)
                         (do {
                            guard
                             (\<lambda>s.
                                 c_guard (new_roots +\<^sub>p uint i));
                            guard (\<lambda>s. num_vals - 1 <s 3);
                            guard (\<lambda>s. 0 \<le>s num_vals - 1);
                            guard
                             (\<lambda>s. - INT_MAX - 1 < sint num_vals);
                            guard
                             (\<lambda>_. sint num_vals \<le> INT_MAX + 1);
                            modify
                             (t_hrs_'_update
                               (hrs_mem_update
                                 (heap_update (new_roots +\<^sub>p uint i)
                                   (vals.[unat (num_vals - 1)]))));
                            tree \<leftarrow>
                              gets
                               (\<lambda>xm.
                                   h_val (hrs_mem (t_hrs_' xm))
                                    (new_roots +\<^sub>p uint i));
                            ret \<leftarrow> binomial_tree_ref' tree;
                            return (i + 1)
                          })
                         (do {
                            guard
                             (\<lambda>_.
                                 c_guard (new_roots +\<^sub>p uint i));
                            modify
                             (t_hrs_'_update
                               (hrs_mem_update
                                 (heap_update (new_roots +\<^sub>p uint i)
                                   NULL)));
                            return new_roots_length
                          }));
                   new_carry \<leftarrow>
                     condition (\<lambda>s. num_vals && 2 \<noteq> 0)
                       (do {
                          new_carry \<leftarrow>
                            liftE
                             (binomial_tree_merge' ?heap (vals.[0])
                               (vals.[1]));
                          ret \<leftarrow>
                            when (new_carry = NULL)
                             (do {
                                ret \<leftarrow>
                                  liftE
                                   (binomial_heap_merge_undo' new_roots i);
                                ret \<leftarrow>
                                  liftE (binomial_tree_unref' carry);
                                throw 0
                              });
                          return new_carry
                        })
                       (return NULL);
                   liftE
                    (do {
                       ret \<leftarrow> binomial_tree_unref' carry;
                       ret \<leftarrow> binomial_tree_ref' new_carry;
                       return (new_carry, i + 1, new_roots_length, vals)
                     })
                 })
            (NULL, 0, 0, vals);
         i \<leftarrow>
           liftE
            (whileLoop (\<lambda>i s.
                           i < roots_length_C
                                (h_val (hrs_mem (t_hrs_' s)) ?heap))
               (\<lambda>i.
                   do {
                     guard
                      (\<lambda>s.
                          c_guard
                           (roots_C
                             (h_val (hrs_mem (t_hrs_' s)) ?heap) +\<^sub>p
                            uint i));
                     ret \<leftarrow>
                       condition (\<lambda>s.
                                     h_val (hrs_mem (t_hrs_' s))
(roots_C (h_val (hrs_mem (t_hrs_' s)) ?heap) +\<^sub>p uint i) \<noteq>
                                     NULL)
                         (gets
                           (\<lambda>xi.
                               h_val (hrs_mem (t_hrs_' xi))
                                (roots_C
                                  (h_val (hrs_mem (t_hrs_' xi))
                                    ?heap) +\<^sub>p
                                 uint i)) >>=
                          binomial_tree_unref')
                         skip;
                     return (i + 1)
                   })
              0);
         ptr \<leftarrow>
           gets
            (\<lambda>xh.
                PTR_COERCE(StrictC'_BinomialTree_C ptr \<rightarrow> unit)
                 (roots_C (h_val (hrs_mem (t_hrs_' xh)) ?heap)));
         ret \<leftarrow> liftE (free' ptr);
         modify
          (t_hrs_'_update
            (\<lambda>a.
                hrs_mem_update
                 (heap_update ?heap
                   (roots_C_update (\<lambda>a. new_roots)
                     (h_val (hrs_mem a) ?heap)))
                 a));
         modify
          (t_hrs_'_update
            (\<lambda>a.
                hrs_mem_update
                 (heap_update ?heap
                   (roots_length_C_update (\<lambda>a. new_roots_length)
                     (h_val (hrs_mem a) ?heap)))
                 a));
         throw 1
       }))
}

binomial_heap_cmp' ?heap ?data1.0 ?data2.0 \<equiv>
do {
  guard (\<lambda>s. c_guard ?heap);
  condition (\<lambda>s.
                heap_type_C (h_val (hrs_mem (t_hrs_' s)) ?heap) =
                BINOMIAL_HEAP_TYPE_MIN)
    (do {
       p \<leftarrow>
         gets
          (\<lambda>xb.
              compare_func_C (h_val (hrs_mem (t_hrs_' xb)) ?heap));
       \<P> p ?data1.0 ?data2.0
     })
    (do {
       p \<leftarrow>
         gets
          (\<lambda>xb.
              compare_func_C (h_val (hrs_mem (t_hrs_' xb)) ?heap));
       ret'int'1 \<leftarrow> \<P> p ?data1.0 ?data2.0;
       x \<leftarrow> guard (\<lambda>_. sint ret'int'1 \<le> INT_MAX + 1);
       guard (\<lambda>_. - sint ret'int'1 \<le> INT_MAX);
       return (- ret'int'1)
     })
}

binomial_heap_free' ?heap \<equiv>
do {
  guard (\<lambda>s. c_guard ?heap);
  i \<leftarrow>
    whileLoop (\<lambda>i s.
                  i < roots_length_C (h_val (hrs_mem (t_hrs_' s)) ?heap))
      (\<lambda>i.
          do {
            guard
             (\<lambda>s.
                 c_guard
                  (roots_C (h_val (hrs_mem (t_hrs_' s)) ?heap) +\<^sub>p
                   uint i));
            tree \<leftarrow>
              gets
               (\<lambda>s.
                   h_val (hrs_mem (t_hrs_' s))
                    (roots_C (h_val (hrs_mem (t_hrs_' s)) ?heap) +\<^sub>p
                     uint i));
            ret \<leftarrow> binomial_tree_unref' tree;
            return (i + 1)
          })
     0;
  ptr \<leftarrow>
    gets
     (\<lambda>s.
         PTR_COERCE(StrictC'_BinomialTree_C ptr \<rightarrow> unit)
          (roots_C (h_val (hrs_mem (t_hrs_' s)) ?heap)));
  ret \<leftarrow> free' ptr;
  free' (PTR_COERCE(StrictC'_BinomialHeap_C \<rightarrow> unit) ?heap)
}

calloc' ?count ?size \<equiv>
do {
  guard (\<lambda>s. binomial_heap_input.calloc.count_' < unat ?count);
  x \<leftarrow>
    guard (\<lambda>s. binomial_heap_input.calloc.count_' < unat ?size);
  x \<leftarrow>
    guard
     (\<lambda>s.
         unat ?count * unat ?size < binomial_heap_input.calloc.ret'_' ^ 64);
  guard (\<lambda>s. allocator_wf (phantom_machine_state_' s));
  assume_result_and_state
   (\<lambda>s.
       {(p, t).
        \<exists>h A.
           calloc_rel (unat ?count) (unat ?size) (hrs_mem (t_hrs_' s))
            (phantom_machine_state_' s) (ptr_val p) h A \<and>
           t =
           t_hrs_'_update (hrs_mem_update (\<lambda>_. h)) s
           \<lparr>phantom_machine_state_' := A\<rparr>})
}

int_compare' ?vlocation1.0 ?vlocation2.0 \<equiv>
do {
  location1 \<leftarrow>
    return (PTR_COERCE(unit \<rightarrow> 32 signed word) ?vlocation1.0);
  location2 \<leftarrow>
    return (PTR_COERCE(unit \<rightarrow> 32 signed word) ?vlocation2.0);
  x \<leftarrow> guard (\<lambda>_. c_guard location2);
  guard (\<lambda>_. c_guard location1);
  condition (\<lambda>s.
                h_val (hrs_mem (t_hrs_' s)) location1
                <s h_val (hrs_mem (t_hrs_' s)) location2)
    (return (- 1))
    (condition (\<lambda>s.
                   h_val (hrs_mem (t_hrs_' s)) location2
                   <s h_val (hrs_mem (t_hrs_' s)) location1)
       (return 1)
       (return 0))
}
